{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "notebook edición video 4K alto rendimiento",
        "category": "notebooks",
        "attributes": {"ram_gb": {"min": 32}},
        "limit": 3
      }
    },
    {
      "id": "s2",
      "op": "compare_products",
      "args": {
        "ids": ["$s1.0.id", "$s1.1.id", "$s1.2.id"]
      }
    },
    {
      "id": "s3",
      "op": "get_reviews",
      "args": {
        "product_id": "$s2.mejor_evaluado",
        "limit": 5
      }
    },
    {
      "id": "s4",
      "op": "respond",
      "plantilla": "¡Hola! Para edición de video 4K necesitas potencia de sobra, y encontré opciones con 32 GB de RAM o más. Tras comparar las alternativas disponibles, el modelo mejor evaluado por otros usuarios es el que te destaco primero.\n\n🏆 Mejor evaluado: {nombre_top} — ${precio_top} CLP <<rec:{id_top}>>\nLo que dicen los usuarios: {resenas}\n\nTambién puedes considerar:\n• {nombre_2} — ${precio_2} CLP <<rec:{id_2}>>\n• {nombre_3} — ${precio_3} CLP <<rec:{id_3}>>\n\nComparación entre las tres opciones: <<cmp:{id_top},{id_2},{id_3}>>\n\nEl más económico del grupo es el de ${precio_barato} CLP. Si quieres más detalles de alguno, con gusto te ayudo.",
      "vars": {
        "nombre_top": "$s2.mejor_evaluado",
        "id_top": "$s2.mejor_evaluado",
        "precio_top": "$s1.0.price_clp",
        "resenas": "$s3",
        "nombre_2": "$s1.1.name",
        "id_2": "$s1.1.id",
        "precio_2": "$s1.1.price_clp",
        "nombre_3": "$s1.2.name",
        "id_3": "$s1.2.id",
        "precio_3": "$s1.2.price_clp",
        "id_comparacion": "$s2.ids",
        "precio_barato": "$s2.mas_barato"
      }
    }
  ]
}
